// Regenerates src/data/products.generated.ts from the public repos of the
// framwrk GitHub org.
//
// - Runs automatically before `bun run build` (see the "prebuild" script).
// - Run manually with `bun run products`.
// - Set GITHUB_TOKEN to raise the GitHub API rate limit (60 requests/hour
//   unauthenticated, 5000 authenticated).
// - If GitHub can't be reached, the existing generated file is kept so the
//   build still succeeds.

const ORG = "framwrk"
const PAGE_SIZE = 100
const OUTPUT_PATH = "src/data/products.generated.ts"

// Public repos that should not appear as products on the site.
const EXCLUDED_REPOS = ["framwrk.com"]

// Card details GitHub doesn't track, keyed by repo name.
const PLATFORM_OVERRIDES: Record<string, string> = {
  pallet: "macOS",
  tret: "macOS",
}

type ApiRepo = {
  name: string
  description: string | null
  html_url: string
  homepage: string | null
  license: { spdx_id: string | null } | null
}

type Product = {
  name: string
  description: string
  repoUrl: string
  homepage?: string
  meta?: string
}

async function readIfExists(path: string): Promise<string | null> {
  try {
    return await Bun.file(path).text()
  } catch {
    return null
  }
}

async function fetchOrgRepos(): Promise<ApiRepo[]> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
  }
  if (process.env.GITHUB_TOKEN) {
    headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`
  }

  const repos: ApiRepo[] = []
  let page = 1
  for (;;) {
    const url = `https://api.github.com/orgs/${ORG}/repos?per_page=${PAGE_SIZE}&page=${page}`
    const response = await fetch(url, { headers })
    if (!response.ok) {
      throw new Error(`GitHub API responded with ${response.status} ${response.statusText}`)
    }
    const batch = (await response.json()) as ApiRepo[]
    repos.push(...batch)
    if (batch.length < PAGE_SIZE) {
      return repos
    }
    page += 1
  }
}

function displayName(repoName: string): string {
  return repoName
    .split(/[-_\s]+/)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ")
}

function toProduct(repo: ApiRepo): Product {
  const homepage = repo.homepage?.trim()
  let website: string | undefined
  if (homepage) {
    try {
      website = new URL(homepage).toString()
    } catch {
      // Ignore a malformed homepage; the card still links the repo.
    }
  }

  const meta = [PLATFORM_OVERRIDES[repo.name], repo.license?.spdx_id]
    .filter(Boolean)
    .join(" · ")

  return {
    name: displayName(repo.name),
    description: repo.description ?? "",
    repoUrl: repo.html_url,
    homepage: website,
    meta: meta || undefined,
  }
}

function renderFile(products: Product[]): string {
  const entries = products.map((product) => `  ${JSON.stringify(product)},`).join("\n")
  return `// Generated by scripts/fetch-products.ts. Do not edit by hand.
// Source: https://github.com/orgs/${ORG}/repositories
// Regenerate with: bun run products

export type Product = {
  name: string
  description: string
  repoUrl: string
  homepage?: string
  meta?: string
}

export const products: Product[] = [
${entries}
]
`
}

let repos: ApiRepo[]
try {
  repos = await fetchOrgRepos()
} catch (error) {
  const message = error instanceof Error ? error.message : String(error)
  const previous = await readIfExists(OUTPUT_PATH)
  if (previous === null) {
    console.error(`Failed to fetch repos from GitHub (${message}) and ${OUTPUT_PATH} does not exist yet.`)
    process.exit(1)
  }
  console.warn(`Warning: could not fetch repos from GitHub (${message}). Keeping the existing ${OUTPUT_PATH}.`)
  process.exit(0)
}

const products = repos
  .filter((repo) => !EXCLUDED_REPOS.includes(repo.name))
  .sort((a, b) => a.name.localeCompare(b.name))
  .map(toProduct)

if (products.length === 0) {
  console.error(`No products found: all public repos in ${ORG} are excluded by EXCLUDED_REPOS.`)
  process.exit(1)
}

const output = renderFile(products)
if ((await readIfExists(OUTPUT_PATH)) === output) {
  console.log(`${OUTPUT_PATH} is up to date (${products.length} products).`)
} else {
  await Bun.write(OUTPUT_PATH, output)
  console.log(`Wrote ${OUTPUT_PATH} (${products.length} products).`)
}
